begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.get_project_draft(uuid)','EXECUTE'),'Anonymous cannot read saved drafts');
select ok(not has_function_privilege('anon','public.create_project_draft(uuid,text,text,text,text,jsonb,jsonb)','EXECUTE'),'Anonymous cannot create drafts');
select ok(not has_function_privilege('authenticated','private.project_draft_json(public.projects)','EXECUTE'),'Browser cannot invoke the unscoped row serializer');
insert into auth.users(id,email) values('d9000000-0000-4000-8000-000000000001','draft-a@example.invalid'),('d9000000-0000-4000-8000-000000000002','draft-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.create_project_draft('d9100000-0000-4000-8000-000000000001','request-one',repeat('a',64),'Untitled education video','education','{"mode":"education","topic":""}','{"targetSeconds":75,"orientation":"portrait","voiceProfileId":"Kore"}')->>'draftVersion','1','Incomplete draft created with first version');
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->'draftInput'->>'topic','','Incomplete input persists');
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->'preferences'->>'orientation','portrait','Preferences persist');
select is(public.create_project_draft('d9100000-0000-4000-8000-000000000002','request-one',repeat('a',64),'Untitled education video','education','{"mode":"education","topic":""}','{}')->>'id','d9100000-0000-4000-8000-000000000001','Replayed key returns original receipt even with a different proposed ID');
select is((select count(*)::integer from public.projects),1,'Retried creation creates no duplicate');
select throws_ok($$select public.create_project_draft('d9100000-0000-4000-8000-000000000002','request-one',repeat('b',64),'Changed','education','{}','{}')$$,'23505',null::text,'Different payload hash cannot reuse create key');
select is(public.update_project_draft('d9100000-0000-4000-8000-000000000001',1,'Edited draft','{"mode":"education","topic":"Water"}','{"targetSeconds":60}')->>'draftVersion','2','Update returns its own atomic new version');
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->>'title','Edited draft','Updated title persists');
select throws_ok($$select public.update_project_draft('d9100000-0000-4000-8000-000000000001',1,'Lost update','{}','{}')$$,'40001',null::text,'Stale editor cannot overwrite');
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->'draftInput'->>'topic','Water','Conflict leaves current data intact');
select is(public.create_project_draft('d9100000-0000-4000-8000-000000000002','request-one',repeat('a',64),'Ignored','education','{}','{}')->>'draftVersion','1','Create retry returns original receipt without overwriting later edits');
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->>'draftVersion','2','Original receipt replay leaves latest draft version untouched');
select throws_ok('select * from public.idempotency_requests','42501',null::text,'Internal create receipts remain private');
select set_config('request.jwt.claims','{"sub":"d9000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001'),null::jsonb,'Other owner and missing draft both read as unavailable');
select throws_ok($$select public.update_project_draft('d9100000-0000-4000-8000-000000000001',2,'Attack','{}','{}')$$,'42501',null::text,'Other owner cannot change draft');
select throws_ok($$select public.create_project_draft('d9100000-0000-4000-8000-000000000001','request-one',repeat('a',64),'Attack','education','{}','{}')$$,'42501',null::text,'Same request key is scoped to owner and cannot claim another ID');
select is(public.create_project_draft('d9100000-0000-4000-8000-000000000002','request-one',repeat('a',64),'Other draft','branding','{}','{}')->>'mode','branding','Same request key can be used independently by another owner');
reset role;
insert into public.revisions(project_id,owner_id,revision_number,input_hash,request_kind,target_seconds,orientation,voice_profile_id,schema_version,prompt_version,composition_version)
values('d9100000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,repeat('a',64),'initial',60,'landscape','Kore',1,'v1','v1');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001')->>'modeLocked','true','Existing revision freezes project mode');
select is(public.update_project_draft('d9100000-0000-4000-8000-000000000001',2,'Edit future draft','{"topic":"New draft"}','{}')->>'mode','education','Future draft edits preserve generated mode');
reset role;
update public.projects set deleted_at=now() where id='d9100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000001'),null::jsonb,'Deleted project cannot be reopened');
select throws_ok($$select public.create_project_draft('d9100000-0000-4000-8000-000000000003','request-one',repeat('a',64),'Resurrect','education','{}','{}')$$,'42501',null::text,'Create replay cannot resurrect deleted project');
reset role;
update public.projects set draft_state='removed' where id='d9100000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d9000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.get_project_draft('d9100000-0000-4000-8000-000000000002'),null::jsonb,'Removed draft cannot be reopened');
reset role;
update public.profiles set status='disabled' where id='d9000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.get_project_draft('d9100000-0000-4000-8000-000000000002')$$,'42501',null::text,'Disabled owner cannot read drafts');
select throws_ok($$select public.create_project_draft('d9100000-0000-4000-8000-000000000003','new-key',repeat('a',64),'Denied','education','{}','{}')$$,'42501',null::text,'Disabled owner cannot create drafts');
reset role;
select is((select count(*)::integer from public.jobs where owner_id in('d9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002')),0,'Draft saving never enqueues a job');
select is((select count(*)::integer from public.usage_reservations where owner_id in('d9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000002')),0,'Draft saving never reserves generation capacity');
select * from finish();
rollback;
